<span class="line" data-line="235"><span class="ln">235</span><span style="color:#569CD6">               MOVE</span><span style="color:#569CD6"> ZEROS</span><span style="color:#569CD6"> TO</span><span style="color:#CCCCCC"> WS-TOTAL-NUM.</span></span>
